from enum import Enum

# ==========================================================
# SIGNAL
# ==========================================================


class Signal(str, Enum):
    """Trading signal generated by Strategy Engine."""

    NONE = "NONE"

    BUY_CE = "BUY_CE"
    BUY_PE = "BUY_PE"

    EXIT = "EXIT"


# ==========================================================
# DECISION STATUS
# ==========================================================


class DecisionStatus(str, Enum):
    """Lifecycle of a strategy decision."""

    NO_SIGNAL = "NO_SIGNAL"
    VALID = "VALID"
    BLOCKED = "BLOCKED"
    EXECUTED = "EXECUTED"
    ERROR = "ERROR"


# ==========================================================
# EXIT REASON
# ==========================================================


class ExitReason(str, Enum):
    """Trade exit reason."""

    NONE = "NONE"
    STOP_LOSS = "STOP_LOSS"
    TRAILING_SL = "TRAILING_SL"
    FORCE_EXIT = "FORCE_EXIT"
    TARGET = "TARGET"
    MANUAL = "MANUAL"
    END_OF_DATA = "END_OF_DATA"


# ==========================================================
# ORDER SIDE
# ==========================================================


class OrderSide(str, Enum):
    """Order direction."""

    BUY = "BUY"
    SELL = "SELL"


# ==========================================================
# ORDER STATUS
# ==========================================================


class OrderStatus(str, Enum):
    """Lifecycle of an order."""

    CREATED = "CREATED"
    PENDING = "PENDING"
    EXECUTED = "EXECUTED"
    REJECTED = "REJECTED"
    CANCELLED = "CANCELLED"


# ==========================================================
# TRADE STATUS
# ==========================================================


class TradeStatus(str, Enum):
    """Lifecycle of a trade."""

    CREATED = "CREATED"
    OPEN = "OPEN"
    CLOSED = "CLOSED"


# ==========================================================
# OPTION TYPE
# ==========================================================


class OptionType(str, Enum):
    """Option contract type."""

    CE = "CE"
    PE = "PE"


# ==========================================================
# BROKER
# ==========================================================


class Broker(str, Enum):
    """Supported brokers."""

    DHAN = "DHAN"
    ZERODHA = "ZERODHA"


# ==========================================================
# TRADING MODE
# ==========================================================


class TradingMode(str, Enum):
    """Trading environment."""

    PAPER = "PAPER"
    LIVE = "LIVE"


# ==========================================================
# MARKET STATE
# ==========================================================


class MarketState(str, Enum):
    """Current market state."""

    PRE_OPEN = "PRE_OPEN"
    OPEN = "OPEN"
    CLOSED = "CLOSED"


# ==========================================================
# LOG LEVEL
# ==========================================================


class LogLevel(str, Enum):
    """Application log levels."""

    DEBUG = "DEBUG"
    INFO = "INFO"
    WARNING = "WARNING"
    ERROR = "ERROR"
    CRITICAL = "CRITICAL"
